"""Data models for diagnostic check results and reports."""

import datetime
from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, Field


class CheckStatus(str, Enum):
    """Status of an individual diagnostic check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    SKIP = "skip"
    ERROR = "error"  # check itself crashed


class CheckResult(BaseModel):
    """Result of a single diagnostic check."""

    name: str  # e.g., "auth.api_key_present"
    category: str  # e.g., "auth", "config", "network"
    status: CheckStatus
    message: str  # Human-readable result
    fix_hint: Optional[str] = None  # How to fix it
    details: Optional[dict[str, Any]] = None  # Extra context for support tickets


class DiagnosticReport(BaseModel):
    """Aggregated report of all diagnostic check results."""

    results: list[CheckResult] = Field(default_factory=list)
    timestamp: str = Field(
        default_factory=lambda: datetime.datetime.now(datetime.timezone.utc).isoformat()
    )
    system_info: dict[str, Any] = Field(default_factory=dict)

    @property
    def passed(self) -> list[CheckResult]:
        """Return all checks that passed."""
        return [r for r in self.results if r.status == CheckStatus.PASS]

    @property
    def warnings(self) -> list[CheckResult]:
        """Return all checks with warnings."""
        return [r for r in self.results if r.status == CheckStatus.WARN]

    @property
    def failures(self) -> list[CheckResult]:
        """Return all checks that failed."""
        return [r for r in self.results if r.status == CheckStatus.FAIL]

    @property
    def errors(self) -> list[CheckResult]:
        """Return all checks that encountered errors."""
        return [r for r in self.results if r.status == CheckStatus.ERROR]

    @property
    def skipped(self) -> list[CheckResult]:
        """Return all checks that were skipped."""
        return [r for r in self.results if r.status == CheckStatus.SKIP]

    def summary(self) -> str:
        """One-line summary of results."""
        p, w, f, e, s = (
            len(self.passed),
            len(self.warnings),
            len(self.failures),
            len(self.errors),
            len(self.skipped),
        )
        total = len(self.results)
        parts = []
        if p:
            parts.append(f"{p} passed")
        if w:
            parts.append(f"{w} warnings")
        if f:
            parts.append(f"{f} failed")
        if e:
            parts.append(f"{e} errors")
        if s:
            parts.append(f"{s} skipped")
        return f"{total} checks: {', '.join(parts)}"

    def to_dict(self) -> dict[str, Any]:
        """Full report as dict for JSON export."""
        return {
            "timestamp": self.timestamp,
            "system_info": self.system_info,
            "summary": self.summary(),
            "results": [r.model_dump() for r in self.results],
        }

    def to_github_issue_body(self) -> str:
        """Format as GitHub issue body markdown."""
        lines = ["## Diagnostic Report", ""]

        # System info
        lines.append("### System Information")
        lines.append("```")
        for k, v in self.system_info.items():
            lines.append(f"{k}: {v}")
        lines.append("```")
        lines.append("")

        # Failures
        if self.failures or self.errors:
            lines.append("### Failures")
            for r in self.failures + self.errors:
                emoji = "\u274c" if r.status == CheckStatus.FAIL else "\U0001f4a5"
                lines.append(f"- {emoji} **{r.name}**: {r.message}")
                if r.fix_hint:
                    lines.append(f"  - Fix: {r.fix_hint}")
                if r.details:
                    lines.append(f"  - Details: `{r.details}`")
            lines.append("")

        # Warnings
        if self.warnings:
            lines.append("### Warnings")
            for r in self.warnings:
                lines.append(f"- \u26a0\ufe0f **{r.name}**: {r.message}")
                if r.fix_hint:
                    lines.append(f"  - Fix: {r.fix_hint}")
            lines.append("")

        # Passed
        if self.passed:
            lines.append("### Passed")
            for r in self.passed:
                lines.append(f"- \u2705 {r.name}")
            lines.append("")

        lines.append("---")
        lines.append("*Generated by `qbraid troubleshoot`*")
        return "\n".join(lines)
